package fraymus.workspace;
import org.json.*;
import java.nio.file.*;
import java.util.*;

/** Research-only scorer. Later masks/references are never supplied to production APIs. */
public final class ObservationFootageEvaluation {
    public static void main(String[] args)throws Exception{
        if(args[0].equals("prepare")){
            var original=new JSONObject(Files.readString(Path.of(args[1])));var frames=original.getJSONArray("frames");var references=new JSONArray();var clean=new JSONArray();PixelTracker.Box initial=null;
            for(int i=0;i<frames.length();i++){var f=frames.getJSONObject(i);var box=TrackingEvaluation.truth(TrackingEvaluation.image(TrackingEvaluation.data(f,"mask"),true),original.getInt("objectId"));if(i==0)initial=box;references.put(new JSONObject().put("sourceFrame",f.getInt("sourceFrame")).put("imageSha256",f.getString("imageSha256")).put("maskSha256",f.getString("maskSha256")).put("box",box==null?JSONObject.NULL:box.json()));var c=new JSONObject();for(String k:List.of("sourceFrame","image","imageSha256"))c.put(k,f.get(k));clean.put(c);}
            if(initial==null)throw new IllegalStateException("First frame requires a human/reference initialization box");
            var pack=new JSONObject().put("schema","fraynix-observation-frames-036-v1").put("title",original.getString("title")).put("source",original.getString("source")).put("license",original.getString("license")).put("clock","source-frame").put("objects",new JSONArray().put(new JSONObject().put("key","subject").put("label",original.getString("sequence")+" subject (human-guided)").put("box",initial.json()))).put("frames",clean);
            Files.writeString(Path.of(args[2]),pack.toString());Files.writeString(Path.of(args[3]),new JSONObject().put("sequence",original.getString("sequence")).put("references",references).toString());System.out.println("Prepared clean pixels and separate scorer-only references: "+frames.length());return;
        }
        var pack=new JSONObject(Files.readString(Path.of(args[1])));Path project=Files.createTempDirectory("observations036-footage-");var ledger=new WorldLedger(project);String world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),pack.getString("title")).getString("id");JSONObject run,state;
        try(var store=new WorldObservationStore(project,ledger)){var dataset=WorldObservationStoreTest.importPack(store,pack);run=WorldObservationStoreTest.settled(store,store.start(WorldObservationStoreTest.arguments(ledger,world,dataset,0)).getString("id"));state=store.state(world);}
        // Score only after the immutable runtime trace exists. References never initialize subsequent steps.
        var refs=new JSONObject(Files.readString(Path.of(args[2])));double iou=0,innovation=0,priorError=0,posteriorError=0;int count=0,visible=0,half=0,accepted=0,errors=0,lost=0,referenceCount=0,measurementCount=0,withinSigma=0;var scoring=new JSONArray();
        for(Object raw:run.getJSONArray("trace")){var step=(JSONObject)raw;var row=step.getJSONArray("objects").getJSONObject(0);var t=row.getJSONObject("tracker");var e=row.getJSONObject("estimate");var truth=refs.getJSONArray("references").getJSONObject(step.getInt("ordinal"));if(truth.getInt("sourceFrame")!=step.getInt("sourceFrame")||!truth.getString("imageSha256").equals(step.getString("imageSha256")))throw new IllegalStateException("Scorer/reference source differs from runtime pixels");var score=WorldFrames.copy(truth).put("ordinal",step.getInt("ordinal"));var box=truth.isNull("box")?null:PixelTracker.Box.from(truth.getJSONArray("box"));var predicted=t.isNull("box")?null:PixelTracker.Box.from(t.getJSONArray("box"));double overlap=box==null||predicted==null?0:PixelTracker.iou(box,predicted);score.put("iou",overlap).put("trackedBox",predicted==null?JSONObject.NULL:predicted.json());scoring.put(score);iou+=overlap;count++;if(overlap>=.5)half++;if(e.getBoolean("accepted"))accepted++;if(predicted==null)lost++;else{visible++;if(overlap<.1)errors++;}if(e.has("innovation")){innovation+=e.getDouble("innovation");measurementCount++;}if(box!=null){referenceCount++;double x=box.x()+box.w()/2,y=box.y()+box.h()/2;double before=Math.hypot(e.getJSONArray("predicted").getDouble(0)-x,e.getJSONArray("predicted").getDouble(1)-y),after=Math.hypot(e.getJSONArray("position").getDouble(0)-x,e.getJSONArray("position").getDouble(1)-y);priorError+=before;posteriorError+=after;if(after<=2*e.getDouble("positionSigma"))withinSigma++;score.put("predictionReferenceError",before).put("updatedReferenceError",after);}}
        var result=new JSONObject().put("sequence",refs.getString("sequence")).put("project",project).put("codeSha256",WorldObservationStore.identity()).put("status",run.getString("status")).put("run",run).put("world",state).put("scoring",scoring).put("metrics",new JSONObject().put("frames",count).put("meanIou",count==0?0:iou/count).put("iouHalfCoverage",count==0?0:half/(double)count).put("acceptedUpdates",accepted).put("lost",lost).put("visibleLowOverlap",errors).put("meanPredictionReferenceError",referenceCount==0?0:priorError/referenceCount).put("meanUpdatedReferenceError",referenceCount==0?0:posteriorError/referenceCount).put("referenceFrames",referenceCount).put("measurementCount",measurementCount).put("meanInnovation",measurementCount==0?0:innovation/measurementCount).put("referenceWithinTwoSigma",referenceCount==0?0:withinSigma/(double)referenceCount)).put("referenceIsolation","Only first rectangle disclosed; references loaded by this scorer after all runtime measurements").put("domain","Image-plane normalized units and source-frame time; no metric/camera calibration claim");
        Files.writeString(Path.of(args[3]),result.toString(2));System.out.println(result.getString("sequence")+" "+result.getJSONObject("metrics"));
    }
}
